import csv, json, math, re
from pathlib import Path
root=Path('/root')
analysis=json.loads((root/'mailer_policy_analysis.json').read_text())
summary=(root/'mailer_policy_summary.md').read_text()
expected_top=['assumptions','medications','totals','recommendation']
expected_assumptions={'patients':150,'fills_45':8,'fills_90':4,'doses_per_fill_45':45,'doses_per_fill_90':90}
expected_med_keys=['medication','mailer_format','price_per_1000_doses_usd','mailer_cost_usd','base_payment_per_fill_150_patients_usd','service_fee_per_fill_150_patients_usd','total_payment_per_fill','annual_drug_cost_45','annual_drug_cost_90','annual_mailer_cost_45','annual_mailer_cost_90','annual_payment_45','annual_payment_90','annual_margin_45','annual_margin_90','margin_difference']
expected_totals=['total_annual_margin_45','total_annual_margin_90','total_difference','absolute_total']
expected_rec=['decision','rule']
errors=[]
if list(analysis.keys())!=expected_top: errors.append(f'top keys {list(analysis.keys())}')
if analysis['assumptions']!=expected_assumptions: errors.append(f'assumptions {analysis["assumptions"]}')
meds=analysis['medications']
if [m['medication'] for m in meds] != sorted(m['medication'] for m in meds): errors.append('medications not sorted')
for i,m in enumerate(meds):
    if list(m.keys())!=expected_med_keys: errors.append(f'med {i} keys {list(m.keys())}')
    for k,v in m.items():
        if k not in ('medication','mailer_format'):
            if not isinstance(v,(int,float)): errors.append(f'{m["medication"]}.{k} not numeric')
            if round(v,2)!=v: errors.append(f'{m["medication"]}.{k} not rounded: {v}')
if list(analysis['totals'].keys())!=expected_totals: errors.append(f'total keys {list(analysis["totals"].keys())}')
for k,v in analysis['totals'].items():
    if not isinstance(v,(int,float)): errors.append(f'total {k} not numeric')
    if round(v,2)!=v: errors.append(f'total {k} not rounded')
if list(analysis['recommendation'].keys())!=expected_rec: errors.append(f'rec keys {list(analysis["recommendation"].keys())}')
if analysis['recommendation']['decision'] not in {'shift_to_90_day','keep_45_day'}: errors.append('bad decision')
# totals consistency
s45=round(sum(m['annual_margin_45'] for m in meds),2)
s90=round(sum(m['annual_margin_90'] for m in meds),2)
sdiff=round(sum(m['margin_difference'] for m in meds),2)
if analysis['totals']['total_annual_margin_45']!=s45: errors.append((analysis['totals']['total_annual_margin_45'],s45))
if analysis['totals']['total_annual_margin_90']!=s90: errors.append((analysis['totals']['total_annual_margin_90'],s90))
if analysis['totals']['total_difference']!=sdiff: errors.append((analysis['totals']['total_difference'],sdiff))
if analysis['totals']['total_difference']!=round(s90-s45,2): errors.append('difference != total90-total45')
if analysis['totals']['absolute_total']!=round(abs(analysis['totals']['total_difference']),2): errors.append('bad abs')
expected_dec='shift_to_90_day' if abs(analysis['totals']['total_difference']) < 8500 else 'keep_45_day'
if analysis['recommendation']['decision'] != expected_dec: errors.append('decision rule mismatch')
# summary checks
nonempty=[line for line in summary.splitlines() if line.strip()]
if not 4 <= len(nonempty) <= 8: errors.append(f'summary nonempty line count {len(nonempty)}')
for needle in [f"{analysis['totals']['total_annual_margin_45']:.2f}", f"{analysis['totals']['total_annual_margin_90']:.2f}", f"{analysis['totals']['absolute_total']:.2f}", analysis['recommendation']['decision']]:
    if needle not in summary: errors.append(f'summary missing {needle}')
# Manual cross-check Apremilast from raw CSV inputs
compound={r['medication']:r for r in csv.DictReader(open(root/'compound_cost.csv'))}
mailer={r['mailer_format']:r for r in csv.DictReader(open(root/'mailer_cost.csv'))}
base={r['medication']:r for r in csv.DictReader(open(root/'base_payment.csv'))}
service={r['medication']:r for r in csv.DictReader(open(root/'service_fee.csv'))}
med='Apremilast 30mg'
price=float(compound[med]['price_per_1000_doses_usd'])
fmt=compound[med]['mailer_format']
mc=float(mailer[fmt]['mailer_cost_usd'])
bp=float(base[med]['base_payment_per_fill_150_patients_usd'])
sf=float(service[med]['service_fee_per_fill_150_patients_usd'])
manual={
'total_payment_per_fill':round(bp+sf,2),
'annual_drug_cost_45':round((price/1000)*45*150*8,2),
'annual_drug_cost_90':round((price/1000)*90*150*4,2),
'annual_mailer_cost_45':round(mc*150*8,2),
'annual_mailer_cost_90':round(mc*150*4,2),
'annual_payment_45':round((bp+sf)*8,2),
'annual_payment_90':round((bp+sf)*4,2),
}
manual['annual_margin_45']=round(manual['annual_payment_45']-manual['annual_drug_cost_45']-manual['annual_mailer_cost_45'],2)
manual['annual_margin_90']=round(manual['annual_payment_90']-manual['annual_drug_cost_90']-manual['annual_mailer_cost_90'],2)
manual['margin_difference']=round(manual['annual_margin_90']-manual['annual_margin_45'],2)
record=next(m for m in meds if m['medication']==med)
for k,v in manual.items():
    if record[k]!=v: errors.append(f'manual {k}: json={record[k]} manual={v}')
print('VALIDATION_RESULT:', 'PASS' if not errors else 'FAIL')
print('Top-level keys:', list(analysis.keys()))
print('Medication count:', len(meds))
print('Sorted medications:', [m['medication'] for m in meds])
print('Totals:', analysis['totals'])
print('Decision:', analysis['recommendation']['decision'])
print('Summary non-empty lines:', len(nonempty))
print('Manual cross-check medication:', med)
print('Manual cross-check values:', manual)
if errors:
    print('ERRORS:', errors)
    raise SystemExit(1)

